mapper.select:
SELECT DISTINCT a.id, a.uuid::text AS uuid, a.title, a.slug, a.summary, u.nickname AS authorNickname, a.view_count AS viewCount, a.like_count AS likeCount, a.published_at AS publishedAt FROM articles a JOIN article_tags at ON a.uuid = at.article_id JOIN users u ON a.author_id = u.id WHERE at.tag_id IN
#{tagId}::uuid
AND a.uuid != #{excludeUuid}::uuid AND a.status = 'PUBLISHED' ORDER BY a.view_count DESC LIMIT #{limit}
